/bin/bash -lc "python - <<'PY'
from apscheduler.schedulers.asyncio import AsyncIOScheduler
s=AsyncIOScheduler()
@s.scheduled_job('interval', seconds=60)
def f(): pass
print('jobs', s.get_jobs(), 'pending', getattr(s, '_pending_jobs', None))
try: print('remove', s.remove_job('f'))
except Exception as e: print(type(e),e)
print('jobs after',s.get_jobs(),'pending',getattr(s,'_pending_jobs',None))
PY"

